import { NextRequest, NextResponse } from 'next/server';
import { addBook, getBooks } from '@/lib/books';

export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    const books = await getBooks();
    return NextResponse.json(books);
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Failed to load books' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const contentType = request.headers.get('content-type') || '';
    let title = '';
    let author = '';
    let notes = '';
    let status: 'reading' | 'finished' = 'reading';

    if (contentType.includes('application/json')) {
      const body = await request.json();
      title = body.title ?? '';
      author = body.author ?? '';
      notes = body.notes ?? '';
      status = body.status === 'finished' ? 'finished' : 'reading';
    } else {
      const formData = await request.formData();
      title = String(formData.get('title') ?? '');
      author = String(formData.get('author') ?? '');
      notes = String(formData.get('notes') ?? '');
      status = formData.get('status') === 'finished' ? 'finished' : 'reading';
    }

    if (!title.trim() || !author.trim()) {
      return NextResponse.json(
        { error: 'Both title and author are required.' },
        { status: 400 }
      );
    }

    const created = await addBook({ title, author, notes, status });
    return NextResponse.json(created, { status: 201 });
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Failed to add book' },
      { status: 400 }
    );
  }
}

