:root {
  --bg: #faf8f5;
  --surface: #ffffff;
  --border: #e6e1da;
  --text: #1f1d1a;
  --muted: #666059;
  --accent: #2c5e43;
  --accent-hover: #214833;
  --accent-soft: #eaf2ee;
  --reading-badge-bg: #fef3c7;
  --reading-badge-text: #92400e;
  --finished-badge-bg: #dcfce7;
  --finished-badge-text: #166534;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.6;
}

a {
  color: inherit;
  text-decoration: none;
}

.container {
  max-width: 860px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  border-bottom: 1px solid var(--border);
  padding-bottom: 1.25rem;
  margin-bottom: 2rem;
}

.site-title {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.85rem;
  font-weight: 700;
  margin: 0;
  letter-spacing: -0.02em;
}

.site-subtitle {
  color: var(--muted);
  font-size: 0.95rem;
  margin: 0.25rem 0 0;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.35rem;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

@media (max-width: 640px) {
  .form-grid {
    grid-template-columns: 1fr;
  }
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1rem;
}

.form-field label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text);
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.95rem;
  font-family: inherit;
  background: #fff;
  color: var(--text);
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  outline: 2px solid var(--accent);
  border-color: transparent;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.55rem 1rem;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-primary {
  background-color: var(--accent);
  color: #ffffff;
}

.btn-primary:hover:not(:disabled) {
  background-color: var(--accent-hover);
}

.btn-secondary {
  background-color: #ffffff;
  color: var(--text);
  border-color: var(--border);
}

.btn-secondary:hover:not(:disabled) {
  background-color: var(--bg);
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 2.25rem 0 1rem;
}

.section-title {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.35rem;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.count-pill {
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 0.8rem;
  background: var(--border);
  color: var(--text);
  padding: 0.1rem 0.55rem;
  border-radius: 999px;
  font-weight: 600;
}

.book-list {
  display: grid;
  gap: 0.9rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.book-item {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
}

@media (max-width: 600px) {
  .book-item {
    flex-direction: column;
  }
}

.book-title-link {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text);
  display: inline-block;
}

.book-title-link:hover {
  color: var(--accent);
  text-decoration: underline;
}

.book-author {
  color: var(--muted);
  font-size: 0.92rem;
  margin: 0.15rem 0 0.45rem;
}

.book-notes-preview {
  color: var(--text);
  font-size: 0.9rem;
  margin: 0.4rem 0 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.badge {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}

.badge-reading {
  background: var(--reading-badge-bg);
  color: var(--reading-badge-text);
}

.badge-finished {
  background: var(--finished-badge-bg);
  color: var(--finished-badge-text);
}

.empty-state {
  color: var(--muted);
  font-style: italic;
  padding: 1.25rem;
  text-align: center;
  background: var(--surface);
  border: 1px dashed var(--border);
  border-radius: 8px;
}

