'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import type { Book } from '@/lib/books';

interface BookTrackerProps {
  initialBooks: Book[];
}

export default function BookTracker({ initialBooks }: BookTrackerProps) {
  const router = useRouter();
  const [books, setBooks] = useState<Book[]>(initialBooks);
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [notes, setNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [updatingId, setUpdatingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const currentlyReading = books.filter((book) => book.status === 'reading');
  const finishedBooks = books.filter((book) => book.status === 'finished');

  async function handleAddBook(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);

    if (!title.trim() || !author.trim()) {
      setError('Please enter both a book title and an author.');
      return;
    }

    setIsSubmitting(true);
    try {
      const response = await fetch('/api/books', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: title.trim(),
          author: author.trim(),
          notes: notes.trim(),
          status: 'reading',
        }),
      });

      if (!response.ok) {
        const data = await response.json().catch(() => ({}));
        throw new Error(data.error || 'Failed to add book');
      }

      const created: Book = await response.json();
      setBooks((prev) => [created, ...prev]);
      setTitle('');
      setAuthor('');
      setNotes('');
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong');
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handleMarkFinished(id: string) {
    setUpdatingId(id);
    setError(null);
    try {
      const response = await fetch(`/api/books/${encodeURIComponent(id)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'finished' }),
      });

      if (!response.ok) {
        throw new Error('Could not mark book as finished');
      }

      const updated: Book = await response.json();
      setBooks((prev) => prev.map((book) => (book.id === id ? updated : book)));
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update book');
    } finally {
      setUpdatingId(null);
    }
  }

  return (
    <div>
      <section className="card" aria-labelledby="add-book-heading">
        <h2
          id="add-book-heading"
          style={{
            marginTop: 0,
            marginBottom: '1rem',
            fontFamily: 'Georgia, serif',
            fontSize: '1.25rem',
          }}
        >
          Add a Book
        </h2>

        <form onSubmit={handleAddBook}>
          <div className="form-grid">
            <div className="form-field">
              <label htmlFor="book-title">Title</label>
              <input
                id="book-title"
                name="title"
                type="text"
                placeholder="e.g. Piranesi"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                required
              />
            </div>

            <div className="form-field">
              <label htmlFor="book-author">Author</label>
              <input
                id="book-author"
                name="author"
                type="text"
                placeholder="e.g. Susanna Clarke"
                value={author}
                onChange={(e) => setAuthor(e.target.value)}
                required
              />
            </div>
          </div>

          <div className="form-field">
            <label htmlFor="book-notes">Notes</label>
            <textarea
              id="book-notes"
              name="notes"
              rows={3}
              placeholder="Initial thoughts, favorite quotes, or chapter notes..."
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />
          </div>

          {error && (
            <p role="alert" style={{ color: '#b91c1c', marginTop: 0, marginBottom: '0.75rem', fontSize: '0.9rem' }}>
              {error}
            </p>
          )}

          <button type="submit" className="btn btn-primary" disabled={isSubmitting}>
            {isSubmitting ? 'Adding...' : 'Add Book'}
          </button>
        </form>
      </section>

      <section aria-labelledby="currently-reading-heading">
        <div className="section-header">
          <h2 id="currently-reading-heading" className="section-title">
            Currently Reading
            <span className="count-pill">{currentlyReading.length}</span>
          </h2>
        </div>

        {currentlyReading.length === 0 ? (
          <p className="empty-state">No books currently being read. Add one above to get started!</p>
        ) : (
          <ul className="book-list" data-testid="currently-reading-list">
            {currentlyReading.map((book) => (
              <li key={book.id} className="card book-item">
                <div>
                  <Link href={`/books/${encodeURIComponent(book.id)}`} className="book-title-link">
                    {book.title}
                  </Link>
                  <p className="book-author">by {book.author}</p>
                  {book.notes && <p className="book-notes-preview">{book.notes}</p>}
                  <div style={{ marginTop: '0.6rem' }}>
                    <Link
                      href={`/books/${encodeURIComponent(book.id)}`}
                      style={{ fontSize: '0.85rem', color: 'var(--accent)', fontWeight: 600 }}
                    >
                      View details &amp; notes &rarr;
                    </Link>
                  </div>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexShrink: 0 }}>
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={() => handleMarkFinished(book.id)}
                    disabled={updatingId === book.id}
                  >
                    {updatingId === book.id ? 'Saving...' : 'Mark as finished'}
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section aria-labelledby="finished-books-heading">
        <div className="section-header">
          <h2 id="finished-books-heading" className="section-title">
            Finished
            <span className="count-pill">{finishedBooks.length}</span>
          </h2>
        </div>

        {finishedBooks.length === 0 ? (
          <p className="empty-state">No finished books yet.</p>
        ) : (
          <ul className="book-list" data-testid="finished-books-list">
            {finishedBooks.map((book) => (
              <li key={book.id} className="card book-item">
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', flexWrap: 'wrap' }}>
                    <Link href={`/books/${encodeURIComponent(book.id)}`} className="book-title-link">
                      {book.title}
                    </Link>
                    <span className="badge badge-finished">Finished</span>
                  </div>
                  <p className="book-author">by {book.author}</p>
                  {book.notes && <p className="book-notes-preview">{book.notes}</p>}
                  <div style={{ marginTop: '0.6rem' }}>
                    <Link
                      href={`/books/${encodeURIComponent(book.id)}`}
                      style={{ fontSize: '0.85rem', color: 'var(--accent)', fontWeight: 600 }}
                    >
                      View details &amp; notes &rarr;
                    </Link>
                  </div>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

