                      href={`/books/${encodeURIComponent(book.id)}`}
                      style={{ fontSize: '0.85rem', color: 'var(--accent)', fontWeight: 600 }}
                    >
                      View details &amp; notes &rarr;
                    </Link>
                  </div>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexShrink: 0 }}>
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={() => handleMarkFinished(book.id)}
                    disabled={updatingId === book.id}
                  >
                    {updatingId === book.id ? 'Saving...' : 'Mark as finished'}
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section aria-labelledby="finished-books-heading">
        <div className="section-header">
          <h2 id="finished-books-heading" className="section-title">
            Finished
            <span className="count-pill">{finishedBooks.length}</span>
          </h2>
        </div>

        {finishedBooks.length === 0 ? (
          <p className="empty-state">No finished books yet.</p>
        ) : (
          <ul className="book-list" data-testid="finished-books-list">
            {finishedBooks.map((book) => (
              <li key={book.id} className="card book-item">
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', flexWrap: 'wrap' }}>
                    <Link href={`/books/${encodeURIComponent(book.id)}`} className="book-title-link">
                      {book.title}
                    </Link>
                    <span className="badge badge-finished">Finished</span>
                  </div>
                  <p className="book-author">by {book.author}</p>
                  {book.notes && <p className="book-notes-preview">{book.notes}</p>}
                  <div style={{ marginTop: '0.6rem' }}>
                    <Link
                      href={`/books/${encodeURIComponent(book.id)}`}
                      style={{ fontSize: '0.85rem', color: 'var(--accent)', fontWeight: 600 }}
                    >
                      View details &amp; notes &rarr;
                    </Link>
                  </div>
                </div>
              </li>
            ))}
