'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import type { Book } from '@/lib/books';

interface BookDetailViewProps {
  initialBook: Book;
}

export default function BookDetailView({ initialBook }: BookDetailViewProps) {
  const router = useRouter();
  const [book, setBook] = useState<Book>(initialBook);
  const [notes, setNotes] = useState(initialBook.notes || '');
  const [isEditingNotes, setIsEditingNotes] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const sharePath = `/books/${encodeURIComponent(book.id)}`;

  async function handleToggleStatus() {
    setIsSaving(true);
    setError(null);
    const nextStatus = book.status === 'finished' ? 'reading' : 'finished';
    try {
      const response = await fetch(`/api/books/${encodeURIComponent(book.id)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: nextStatus }),
      });

      if (!response.ok) {
        throw new Error('Failed to update status');
      }

      const updated: Book = await response.json();
      setBook(updated);
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not update status');
    } finally {
      setIsSaving(false);
    }
  }

  async function handleSaveNotes(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setIsSaving(true);
    setError(null);
    try {
      const response = await fetch(`/api/books/${encodeURIComponent(book.id)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ notes }),
      });

      if (!response.ok) {
        throw new Error('Failed to save notes');
      }

      const updated: Book = await response.json();
      setBook(updated);
      setIsEditingNotes(false);
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not save notes');
    } finally {
      setIsSaving(false);
    }
  }

  async function handleCopyLink() {
    const url = typeof window !== 'undefined' ? window.location.href : sharePath;
    try {
      if (navigator?.clipboard?.writeText) {
        await navigator.clipboard.writeText(url);
      }
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      setCopied(false);
    }
  }

  return (
    <div>
      <div style={{ marginBottom: '1.25rem' }}>
        <Link
          href="/"
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: '0.35rem',
            fontSize: '0.92rem',
            fontWeight: 600,
            color: 'var(--accent)',
          }}
        >
          &larr; Back to all books
        </Link>
      </div>

      <article className="card">
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'flex-start',
            gap: '1rem',
            flexWrap: 'wrap',
            borderBottom: '1px solid var(--border)',
            paddingBottom: '1.25rem',
            marginBottom: '1.25rem',
          }}
        >
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap' }}>
              <h2
                style={{
                  fontFamily: 'Georgia, serif',
                  fontSize: '1.75rem',
                  margin: 0,
                }}
              >
                {book.title}
              </h2>
              <span
                className={`badge ${book.status === 'finished' ? 'badge-finished' : 'badge-reading'}`}
              >
                {book.status === 'finished' ? 'Finished' : 'Currently Reading'}
              </span>
            </div>
            <p
              style={{
                color: 'var(--muted)',
                fontSize: '1.05rem',
                margin: '0.35rem 0 0',
              }}
            >
              by {book.author}
            </p>
          </div>

          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
            <button
              type="button"
              className="btn btn-secondary"
              onClick={handleCopyLink}
            >
              {copied ? 'Link copied!' : 'Copy link to book'}
            </button>

            <button
              type="button"
              className={book.status === 'reading' ? 'btn btn-primary' : 'btn btn-secondary'}
              onClick={handleToggleStatus}
              disabled={isSaving}
            >
              {book.status === 'reading' ? 'Mark as finished' : 'Move to Currently Reading'}
            </button>
          </div>
        </div>

        {error && (
          <p role="alert" style={{ color: '#b91c1c', marginBottom: '1rem' }}>
            {error}
          </p>
        )}

        <section aria-labelledby="book-notes-heading">
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: '0.75rem',
            }}
          >
            <h3
              id="book-notes-heading"
              style={{
                fontFamily: 'Georgia, serif',
                fontSize: '1.2rem',
                margin: 0,
              }}
            >
              My Notes
            </h3>
            {!isEditingNotes && (
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setIsEditingNotes(true)}
                style={{ padding: '0.35rem 0.75rem', fontSize: '0.82rem' }}
              >
                Edit notes
              </button>
            )}
          </div>

          {isEditingNotes ? (
            <form onSubmit={handleSaveNotes}>
              <div className="form-field">
                <label htmlFor="edit-notes-textarea" style={{ display: 'none' }}>
                  Notes
                </label>
                <textarea
                  id="edit-notes-textarea"
                  rows={5}
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="Write your notes about this book..."
                />
              </div>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <button type="submit" className="btn btn-primary" disabled={isSaving}>
                  {isSaving ? 'Saving...' : 'Save notes'}
                </button>
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => {
                    setNotes(book.notes || '');
                    setIsEditingNotes(false);
                  }}
                  disabled={isSaving}
                >
                  Cancel
                </button>
              </div>
            </form>
          ) : book.notes ? (
            <div
              style={{
                whiteSpace: 'pre-wrap',
                background: 'var(--bg)',
                padding: '1rem 1.15rem',
                borderRadius: '8px',
                border: '1px solid var(--border)',
              }}
            >
              {book.notes}
            </div>
          ) : (
            <p className="empty-state" style={{ margin: 0 }}>
              No notes added for this book yet.
            </p>
          )}
        </section>

        <div
          style={{
            marginTop: '1.5rem',
            paddingTop: '1rem',
            borderTop: '1px solid var(--border)',
            fontSize: '0.85rem',
            color: 'var(--muted)',
            display: 'flex',
            justifyContent: 'space-between',
            flexWrap: 'wrap',
            gap: '0.5rem',
          }}
        >
          <span>
            Direct link: <code>{sharePath}</code>
          </span>
          {book.finishedAt && (
            <span>Finished on {new Date(book.finishedAt).toLocaleDateString()}</span>
          )}
        </div>
      </article>
    </div>
  );
}

