                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => {
                    setNotes(book.notes || '');
                    setIsEditingNotes(false);
                  }}
                  disabled={isSaving}
                >
                  Cancel
                </button>
              </div>
            </form>
          ) : book.notes ? (
            <div
              style={{
                whiteSpace: 'pre-wrap',
                background: 'var(--bg)',
                padding: '1rem 1.15rem',
                borderRadius: '8px',
                border: '1px solid var(--border)',
              }}
            >
              {book.notes}
            </div>
          ) : (
            <p className="empty-state" style={{ margin: 0 }}>
              No notes added for this book yet.
            </p>
          )}
        </section>

        <div
          style={{
            marginTop: '1.5rem',
            paddingTop: '1rem',
            borderTop: '1px solid var(--border)',
            fontSize: '0.85rem',
            color: 'var(--muted)',
            display: 'flex',
            justifyContent: 'space-between',
            flexWrap: 'wrap',
            gap: '0.5rem',
          }}
        >
          <span>
            Direct link: <code>{sharePath}</code>
