import type { Metadata } from 'next';
import Link from 'next/link';
import { getBookById } from '@/lib/books';
import BookDetailView from '@/components/BookDetailView';

export const dynamic = 'force-dynamic';

interface BookPageProps {
  params: Promise<{ id: string }>;
}

export async function generateMetadata({ params }: BookPageProps): Promise<Metadata> {
  const { id } = await params;
  const book = await getBookById(id);

  if (!book) {
    return {
      title: 'Book Not Found — Reading Shelf',
    };
  }

  return {
    title: `${book.title} by ${book.author} — Reading Shelf`,
    description: book.notes || `Reading notes for ${book.title} by ${book.author}`,
  };
}

export default async function BookDetailPage({ params }: BookPageProps) {
  const { id } = await params;
  const book = await getBookById(id);

  if (!book) {
    return (
      <div className="card" style={{ textAlign: 'center', padding: '2.5rem 1.5rem' }}>
        <h2 style={{ fontFamily: 'Georgia, serif', marginTop: 0 }}>Book not found</h2>
        <p style={{ color: 'var(--muted)', marginBottom: '1.5rem' }}>
          We couldn&apos;t find a book matching this link.
        </p>
        <Link href="/" className="btn btn-primary">
          &larr; Back to all books
        </Link>
      </div>
    );
  }

  return <BookDetailView initialBook={book} />;
}

