import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { NextRequest } from 'next/server';
import { addBook, getBookById, getBooks, markBookFinished, updateBook } from '@/lib/books';
import { GET as getBooksRoute, POST as postBookRoute } from '@/app/api/books/route';
import { GET as getBookByIdRoute, PATCH as patchBookRoute } from '@/app/api/books/[id]/route';

describe('Book JSON persistence and API routes', () => {
  let tempDir: string;
  let tempBooksFile: string;

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'reading-tracker-test-'));
    tempBooksFile = path.join(tempDir, 'books.json');
    process.env.BOOKS_FILE_PATH = tempBooksFile;
  });

  afterEach(async () => {
    delete process.env.BOOKS_FILE_PATH;
    await fs.rm(tempDir, { recursive: true, force: true });
  });

  it('initializes an empty JSON file and adds a book that persists on disk', async () => {
    const initial = await getBooks();
    expect(initial).toEqual([]);

    const created = await addBook({
      title: 'Project Hail Mary',
      author: 'Andy Weir',
      notes: 'Exciting sci-fi survival story.',
