import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';

export type BookStatus = 'reading' | 'finished';

export interface Book {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  createdAt: string;
  finishedAt?: string | null;
}

export interface CreateBookInput {
  title: string;
  author: string;
  notes?: string;
  status?: BookStatus;
}

export interface UpdateBookInput {
  title?: string;
  author?: string;
  notes?: string;
  status?: BookStatus;
}

export function getBooksFilePath(): string {
  if (process.env.BOOKS_FILE_PATH) {
    return path.resolve(process.env.BOOKS_FILE_PATH);
  }
  return path.join(process.cwd(), 'data', 'books.json');
}

async function ensureBooksFile(filePath: string): Promise<void> {
  try {
    await fs.access(filePath);
  } catch {
    await fs.mkdir(path.dirname(filePath), { recursive: true });
    await fs.writeFile(filePath, JSON.stringify([], null, 2), 'utf-8');
  }
}

export async function getBooks(): Promise<Book[]> {
  const filePath = getBooksFilePath();
  await ensureBooksFile(filePath);
  const raw = await fs.readFile(filePath, 'utf-8');
  if (!raw.trim()) {
    return [];
  }
  const parsed = JSON.parse(raw);
  return Array.isArray(parsed) ? parsed : [];
}

async function saveBooks(books: Book[]): Promise<void> {
  const filePath = getBooksFilePath();
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, JSON.stringify(books, null, 2), 'utf-8');
}

export async function getBookById(id: string): Promise<Book | null> {
  const books = await getBooks();
  const decodedId = decodeURIComponent(id);
  return books.find((b) => b.id === decodedId || b.id === id) ?? null;
}

function createBookId(title: string, existingIds: Set<string>): string {
  const baseSlug = title
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 48);

  const fallback = baseSlug || 'book';
  if (!existingIds.has(fallback)) {
    return fallback;
  }
  const shortSuffix = crypto.randomUUID().slice(0, 6);
  return `${fallback}-${shortSuffix}`;
}

export async function addBook(input: CreateBookInput): Promise<Book> {
  const title = input.title?.trim();
  const author = input.author?.trim();
  const notes = (input.notes ?? '').trim();
  const status: BookStatus = input.status === 'finished' ? 'finished' : 'reading';

  if (!title) {
    throw new Error('Title is required');
  }
  if (!author) {
    throw new Error('Author is required');
  }

  const books = await getBooks();
  const existingIds = new Set(books.map((b) => b.id));
  const now = new Date().toISOString();

  const newBook: Book = {
    id: createBookId(title, existingIds),
    title,
    author,
    notes,
    status,
    createdAt: now,
    finishedAt: status === 'finished' ? now : null,
  };

  books.unshift(newBook);
  await saveBooks(books);
  return newBook;
}

export async function markBookFinished(id: string): Promise<Book | null> {
  return updateBook(id, { status: 'finished' });
}

export async function updateBook(id: string, updates: UpdateBookInput): Promise<Book | null> {
  const books = await getBooks();
  const decodedId = decodeURIComponent(id);
  const index = books.findIndex((b) => b.id === decodedId || b.id === id);

  if (index === -1) {
    return null;
  }

  const current = books[index];
  const nextStatus = updates.status ?? current.status;
  let finishedAt = current.finishedAt ?? null;

  if (nextStatus === 'finished' && current.status !== 'finished') {
    finishedAt = new Date().toISOString();
  } else if (nextStatus === 'reading') {
    finishedAt = null;
  }

  const updated: Book = {
    ...current,
    title: updates.title !== undefined ? updates.title.trim() || current.title : current.title,
    author: updates.author !== undefined ? updates.author.trim() || current.author : current.author,
    notes: updates.notes !== undefined ? updates.notes : current.notes,
    status: nextStatus,
    finishedAt,
  };

  books[index] = updated;
  await saveBooks(books);
  return updated;
}

export async function deleteBook(id: string): Promise<boolean> {
  const books = await getBooks();
  const decodedId = decodeURIComponent(id);
  const filtered = books.filter((b) => b.id !== decodedId && b.id !== id);
  if (filtered.length === books.length) {
    return false;
  }
  await saveBooks(filtered);
  return true;
}

